import { findById, validateExists } from './users.js';
import { canDelete } from './permissions.js';
import { Cache } from './cache.js';
import { record, AuditEntry } from './audit.js';

export type Task = {
  id: string;
  title: string;
  description: string;
  status: 'open' | 'in_progress' | 'done';
  createdBy: string;
  assignee: string;
  createdAt: number;
};

const VALID_TRANSITIONS: Record<Task['status'], Task['status'][]> = {
  open: ['in_progress'],
  in_progress: ['done'],
  done: [],
};

class TaskManager {
  private tasks = new Map<string, Task>();
  private cache = new Cache();

  create(input: Omit<Task, 'id' | 'createdAt'>): Task {
    if (!input.title || input.title.trim() === '') {
      throw new Error('Title is required');
    }
    validateExists(input.createdBy);
    validateExists(input.assignee);

    const task: Task = {
      ...input,
      id: Math.random().toString(36).slice(2),
      createdAt: Date.now(),
    };
    this.tasks.set(task.id, task);

    this.cache.set(task.id, task, 60000);
    record({
      action: 'create',
      userId: input.createdBy,
      taskId: task.id,
      timestamp: Date.now(),
    } as AuditEntry);

    return task;
  }

  getTask(id: string): Task | null {
    return this.tasks.get(id) ?? null;
  }

  updateStatus(id: string, status: Task['status']): Task | null {
    const task = this.tasks.get(id);
    if (!task) return null;

    const allowed = VALID_TRANSITIONS[task.status];
    if (!allowed.includes(status)) {
      throw new Error(`Invalid status transition from ${task.status} to ${status}`);
    }

    task.status = status;
    this.cache.invalidate(id);
    record({
      action: 'status_change',
      userId: task.createdBy,
      taskId: id,
      timestamp: Date.now(),
    } as AuditEntry);

    return task;
  }

  delete(id: string, userId: string): boolean {
    const task = this.tasks.get(id);
    if (!task) return false;

    if (!canDelete(task, userId)) {
      return false;
    }

    this.tasks.delete(id);
    this.cache.invalidate(id);
    record({
      action: 'delete',
      userId,
      taskId: id,
      timestamp: Date.now(),
    } as AuditEntry);

    return true;
  }

  listByUser(userId: string): Task[] {
    return Array.from(this.tasks.values()).filter(
      (t) => t.assignee === userId || t.createdBy === userId,
    );
  }

  listAll(): Task[] {
    return Array.from(this.tasks.values());
  }

  clear() {
    this.tasks.clear();
  }
}

export const taskManager = new TaskManager();
