import { taskManager } from './tasks.js';
import { canExport } from './permissions.js';
import { record } from './audit.js';

function escapeCsvField(value: string): string {
  if (value.includes(',') || value.includes('"') || value.includes('\n')) {
    return '"' + value.replace(/"/g, '""') + '"';
  }
  return value;
}

export function exportTasks(userId: string): string {
  if (!canExport(userId)) {
    throw new Error('User does not have export permission');
  }

  const tasks = taskManager.listAll();
  const header = 'id,title,status,assignee,createdAt';
  const rows = tasks.map((task) => {
    return [
      escapeCsvField(task.id),
      escapeCsvField(task.title),
      escapeCsvField(task.status),
      escapeCsvField(task.assignee),
      escapeCsvField(String(task.createdAt)),
    ].join(',');
  });

  record({ action: 'export', userId, timestamp: Date.now() });

  return [header, ...rows].join('\n');
}
